static const z_t5938_t _zag1608 = { { .data = "win_sep", .size = 7 }, { .length = 1, .data = _zag1607 }, { .length = 0, .data = NULL }, { .data = "static int z_win_sep(char c) {\n    return c == '\\\\' || c == '/';\n}", .size = 66 } };
